  1→package jlsm.indexing;
  2→
  3→import jlsm.core.indexing.InvertedIndex;
  4→import jlsm.core.io.MemorySerializer;
  5→import jlsm.core.model.Entry;
  6→import jlsm.core.tree.LsmTree;
  7→
  8→import java.io.IOException;
  9→import java.lang.foreign.MemorySegment;
 10→import java.lang.foreign.ValueLayout;
 11→import java.nio.charset.StandardCharsets;
 12→import java.util.Collection;
 13→import java.util.Iterator;
 14→import java.util.NoSuchElementException;
 15→import java.util.Objects;
 16→
 17→/**
 18→ * Non-instantiable namespace class containing three concrete {@link InvertedIndex} implementations,
 19→ * one per term type.
 20→ *
 21→ * <ul>
 22→ * <li>{@link StringTermed} — UTF-8 String terms
 23→ * <li>{@link LongTermed} — {@code long} terms (sign-bit-flipped big-endian for correct ordering)
 24→ * <li>{@link SegmentTermed} — raw {@link MemorySegment} terms
 25→ * </ul>
 26→ *
 27→ * <p>
 28→ * Obtain instances via the factory methods {@link #stringTermedBuilder()},
 29→ * {@link #longTermedBuilder()}, and {@link #segmentTermedBuilder()}.
 30→ *
 31→ * <h2>Composite key encoding</h2>
 32→ *
 33→ * <pre>
 34→ *   [4-byte big-endian term length][term bytes][doc-id bytes]
 35→ * </pre>
 36→ *
 37→ * All postings for the same term sort contiguously. A range scan for a term uses:
 38→ * <ul>
 39→ * <li>{@code scanStart = [termLen_be4][termBytes]} — sorts before all composite keys for this term
 40→ * because a prefix key sorts before any longer key with the same prefix under unsigned lex order
 41→ * <li>{@code scanEnd = incrementPrefix(scanStart)} — the lexicographic successor of the prefix;
 42→ * {@code null} on overflow → fall back to unbounded scan + prefix check in {@link DocIdIterator}
 43→ * </ul>
 44→ */
 45→public final class LsmInvertedIndex {
 46→
 47→    private LsmInvertedIndex() {
 48→        throw new UnsupportedOperationException("utility class");
 49→    }
 50→
 51→    // -----------------------------------------------------------------------
 52→    // Factory methods
 53→    // -----------------------------------------------------------------------
 54→
 55→    /** Returns a builder for a {@link InvertedIndex.StringTermed} backed by an {@link LsmTree}. */
 56→    public static <D> StringTermed.Builder<D> stringTermedBuilder() {
 57→        return new StringTermed.Builder<>();
 58→    }
 59→
 60→    /** Returns a builder for a {@link InvertedIndex.LongTermed} backed by an {@link LsmTree}. */
 61→    public static <D> LongTermed.Builder<D> longTermedBuilder() {
 62→        return new LongTermed.Builder<>();
 63→    }
 64→
 65→    /** Returns a builder for a {@link InvertedIndex.SegmentTermed} backed by an {@link LsmTree}. */
 66→    public static <D> SegmentTermed.Builder<D> segmentTermedBuilder() {
 67→        return new SegmentTermed.Builder<>();
 68→    }
 69→
 70→    // -----------------------------------------------------------------------
 71→    // Shared composite-key encoding helpers
 72→    // -----------------------------------------------------------------------
 73→
 74→    /**
 75→     * Builds the 4-byte big-endian prefix {@code [termLen | termBytes]}. This sorts before all
 76→     * composite keys for this term.
 77→     */
 78→    static byte[] buildPrefix(byte[] termBytes) {
 79→        assert termBytes != null : "termBytes must not be null";
 80→        byte[] prefix = new byte[4 + termBytes.length];
 81→        int len = termBytes.length;
 82→        prefix[0] = (byte) ((len >>> 24) & 0xFF);
 83→        prefix[1] = (byte) ((len >>> 16) & 0xFF);
 84→        prefix[2] = (byte) ((len >>> 8) & 0xFF);
 85→        prefix[3] = (byte) (len & 0xFF);
 86→        System.arraycopy(termBytes, 0, prefix, 4, termBytes.length);
 87→        return prefix;
 88→    }
 89→
 90→    /**
 91→     * Increments {@code prefix} as a big-endian unsigned integer. Returns {@code null} on overflow
 92→     * (all bytes are {@code 0xFF}), indicating an unbounded scan is needed.
 93→     */
 94→    static MemorySegment incrementPrefix(byte[] prefix) {
 95→        assert prefix != null : "prefix must not be null";
 96→        byte[] incremented = prefix.clone();
 97→        for (int i = incremented.length - 1; i >= 0; i--) {
 98→            if ((incremented[i] & 0xFF) < 0xFF) {
 99→                incremented[i]++;
100→                return MemorySegment.ofArray(incremented);
101→            }
102→            incremented[i] = 0;
103→        }
104→        return null; // overflow
105→    }
106→
107→    /**
108→     * Builds a composite key {@code [termLen_be4 | termBytes | docIdBytes]}.
109→     */
110→    static MemorySegment compositeKey(byte[] termBytes, byte[] docIdBytes) {
111→        assert termBytes != null : "termBytes must not be null";
112→        assert docIdBytes != null : "docIdBytes must not be null";
113→        byte[] prefix = buildPrefix(termBytes);
114→        byte[] key = new byte[prefix.length + docIdBytes.length];
115→        System.arraycopy(prefix, 0, key, 0, prefix.length);
116→        System.arraycopy(docIdBytes, 0, key, prefix.length, docIdBytes.length);
117→        return MemorySegment.ofArray(key);
118→    }
119→
120→    /**
121→     * Encodes a {@code long} term as 8 big-endian bytes with the sign bit flipped so that
122→     * byte-lexicographic order matches numeric order.
123→     */
124→    static byte[] encodeLongTerm(long term) {
125→        long unsigned = term ^ Long.MIN_VALUE;
126→        byte[] bytes = new byte[8];
127→        for (int i = 7; i >= 0; i--) {
128→            bytes[i] = (byte) (unsigned & 0xFF);
129→            unsigned >>>= 8;
130→        }
131→        return bytes;
132→    }
133→
134→    // -----------------------------------------------------------------------
135→    // Shared builder base
136→    // -----------------------------------------------------------------------
137→
138→    private abstract static class AbstractBuilder<D, B extends AbstractBuilder<D, B>> {
139→
140→        LsmTree lsmTree;
141→        MemorySerializer<D> docIdSerializer;
142→
143→        @SuppressWarnings("unchecked")
144→        public B lsmTree(LsmTree lsmTree) {
145→            this.lsmTree = Objects.requireNonNull(lsmTree, "lsmTree must not be null");
146→            return (B) this;
147→        }
148→
149→        @SuppressWarnings("unchecked")
150→        public B docIdSerializer(MemorySerializer<D> docIdSerializer) {
151→            this.docIdSerializer = Objects.requireNonNull(docIdSerializer,
152→                    "docIdSerializer must not be null");
153→            return (B) this;
154→        }
155→    }
156→
157→    // -----------------------------------------------------------------------
158→    // DocIdIterator — shared across all three variants
159→    // -----------------------------------------------------------------------
160→
161→    /**
162→     * Iterates over document IDs from an LSM scan iterator, prefix-checking each composite key and
163→     * skipping tombstones.
164→     *
165→     * @param <D> the document ID type
166→     */
167→    static final class DocIdIterator<D> implements Iterator<D> {
168→
169→        private final Iterator<Entry> delegate;
170→        private final byte[] termPrefix;
171→        private final MemorySerializer<D> docIdSerializer;
172→        private D next;
173→
174→        DocIdIterator(Iterator<Entry> delegate, byte[] termPrefix,
175→                MemorySerializer<D> docIdSerializer) {
176→            assert delegate != null : "delegate must not be null";
177→            assert termPrefix != null : "termPrefix must not be null";
178→            assert docIdSerializer != null : "docIdSerializer must not be null";
179→            this.delegate = delegate;
180→            this.termPrefix = termPrefix;
181→            this.docIdSerializer = docIdSerializer;
182→            advance();
183→        }
184→
185→        private void advance() {
186→            next = null;
187→            while (delegate.hasNext()) {
188→                Entry entry = delegate.next();
189→                // Check prefix match
190→                MemorySegment key = entry.key();
191→                if (!hasPrefix(key, termPrefix)) {
192→                    return;
193→                }
194→                // Skip tombstones
195→                if (entry instanceof Entry.Delete) {
196→                    continue;
197→                }
198→                // Extract docId bytes (everything after the prefix)
199→                long prefixLen = termPrefix.length;
200→                long keyLen = key.byteSize();
201→                assert keyLen > prefixLen : "composite key must be longer than prefix";
202→                MemorySegment docIdSegment = key.asSlice(prefixLen, keyLen - prefixLen);
203→                next = docIdSerializer.deserialize(docIdSegment);
204→                return;
205→            }
206→        }
207→
208→        private static boolean hasPrefix(MemorySegment key, byte[] prefix) {
209→            if (key.byteSize() < prefix.length) {
210→                return false;
211→            }
212→            for (int i = 0; i < prefix.length; i++) {
213→                if (key.get(ValueLayout.JAVA_BYTE, i) != prefix[i]) {
214→                    return false;
215→                }
216→            }
217→            return true;
218→        }
219→
220→        @Override
221→        public boolean hasNext() {
222→            return next != null;
223→        }
224→
225→        @Override
226→        public D next() {
227→            if (next == null) {
228→                throw new NoSuchElementException();
229→            }
230→            D result = next;
231→            advance();
232→            return result;
233→        }
234→    }
235→
236→    // -----------------------------------------------------------------------
237→    // StringTermed
238→    // -----------------------------------------------------------------------
239→
240→    /**
241→     * An {@link InvertedIndex.StringTermed} that delegates to an {@link LsmTree} and encodes terms
242→     * as UTF-8 bytes within a composite key.
243→     *
244→     * @param <D> the document ID type
245→     */
246→    public static final class StringTermed<D> implements InvertedIndex.StringTermed<D> {
247→
248→        private final LsmTree lsmTree;
249→        private final MemorySerializer<D> docIdSerializer;
250→
251→        private StringTermed(LsmTree lsmTree, MemorySerializer<D> docIdSerializer) {
252→            assert lsmTree != null : "lsmTree must not be null";
253→            assert docIdSerializer != null : "docIdSerializer must not be null";
254→            this.lsmTree = lsmTree;
255→            this.docIdSerializer = docIdSerializer;
256→        }
257→
258→        @Override
259→        public void index(D docId, Collection<String> terms) throws IOException {
260→            Objects.requireNonNull(docId, "docId must not be null");
261→            Objects.requireNonNull(terms, "terms must not be null");
262→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
263→            for (String term : terms) {
264→                Objects.requireNonNull(term, "term must not be null");
265→                byte[] termBytes = term.getBytes(StandardCharsets.UTF_8);
266→                MemorySegment key = compositeKey(termBytes, docIdBytes);
267→                lsmTree.put(key, MemorySegment.NULL);
268→            }
269→        }
270→
271→        @Override
272→        public void remove(D docId, Collection<String> terms) throws IOException {
273→            Objects.requireNonNull(docId, "docId must not be null");
274→            Objects.requireNonNull(terms, "terms must not be null");
275→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
276→            for (String term : terms) {
277→                Objects.requireNonNull(term, "term must not be null");
278→                byte[] termBytes = term.getBytes(StandardCharsets.UTF_8);
279→                MemorySegment key = compositeKey(termBytes, docIdBytes);
280→                lsmTree.delete(key);
281→            }
282→        }
283→
284→        @Override
285→        public Iterator<D> lookup(String term) throws IOException {
286→            Objects.requireNonNull(term, "term must not be null");
287→            byte[] termBytes = term.getBytes(StandardCharsets.UTF_8);
288→            return doLookup(termBytes);
289→        }
290→
291→        private Iterator<D> doLookup(byte[] termBytes) throws IOException {
292→            byte[] prefix = buildPrefix(termBytes);
293→            MemorySegment scanEnd = incrementPrefix(prefix);
294→            Iterator<Entry> entries;
295→            if (scanEnd != null) {
296→                entries = lsmTree.scan(MemorySegment.ofArray(prefix), scanEnd);
297→            } else {
298→                // Overflow (all-0xFF prefix) — use unbounded scan; DocIdIterator prefix-checks.
299→                // Unreachable in practice: requires a ~4GB term.
300→                entries = lsmTree.scan();
301→            }
302→            return new DocIdIterator<>(entries, prefix, docIdSerializer);
303→        }
304→
305→        @Override
306→        public void close() throws IOException {
307→            lsmTree.close();
308→        }
309→
310→        /** Builder for {@link LsmInvertedIndex.StringTermed}. */
311→        public static final class Builder<D> extends AbstractBuilder<D, Builder<D>> {
312→
313→            public InvertedIndex.StringTermed<D> build() {
314→                Objects.requireNonNull(lsmTree, "lsmTree must not be null");
315→                Objects.requireNonNull(docIdSerializer, "docIdSerializer must not be null");
316→                return new LsmInvertedIndex.StringTermed<>(lsmTree, docIdSerializer);
317→            }
318→        }
319→    }
320→
321→    // -----------------------------------------------------------------------
322→    // LongTermed
323→    // -----------------------------------------------------------------------
324→
325→    /**
326→     * An {@link InvertedIndex.LongTermed} that delegates to an {@link LsmTree} and encodes terms as
327→     * sign-bit-flipped big-endian 8 bytes within a composite key.
328→     *
329→     * @param <D> the document ID type
330→     */
331→    public static final class LongTermed<D> implements InvertedIndex.LongTermed<D> {
332→
333→        private final LsmTree lsmTree;
334→        private final MemorySerializer<D> docIdSerializer;
335→
336→        private LongTermed(LsmTree lsmTree, MemorySerializer<D> docIdSerializer) {
337→            assert lsmTree != null : "lsmTree must not be null";
338→            assert docIdSerializer != null : "docIdSerializer must not be null";
339→            this.lsmTree = lsmTree;
340→            this.docIdSerializer = docIdSerializer;
341→        }
342→
343→        @Override
344→        public void index(D docId, Collection<Long> terms) throws IOException {
345→            Objects.requireNonNull(docId, "docId must not be null");
346→            Objects.requireNonNull(terms, "terms must not be null");
347→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
348→            for (Long term : terms) {
349→                Objects.requireNonNull(term, "term must not be null");
350→                byte[] termBytes = encodeLongTerm(term);
351→                MemorySegment key = compositeKey(termBytes, docIdBytes);
352→                lsmTree.put(key, MemorySegment.NULL);
353→            }
354→        }
355→
356→        @Override
357→        public void remove(D docId, Collection<Long> terms) throws IOException {
358→            Objects.requireNonNull(docId, "docId must not be null");
359→            Objects.requireNonNull(terms, "terms must not be null");
360→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
361→            for (Long term : terms) {
362→                Objects.requireNonNull(term, "term must not be null");
363→                byte[] termBytes = encodeLongTerm(term);
364→                MemorySegment key = compositeKey(termBytes, docIdBytes);
365→                lsmTree.delete(key);
366→            }
367→        }
368→
369→        @Override
370→        public Iterator<D> lookup(long term) throws IOException {
371→            byte[] termBytes = encodeLongTerm(term);
372→            byte[] prefix = buildPrefix(termBytes);
373→            MemorySegment scanEnd = incrementPrefix(prefix);
374→            Iterator<Entry> entries;
375→            if (scanEnd != null) {
376→                entries = lsmTree.scan(MemorySegment.ofArray(prefix), scanEnd);
377→            } else {
378→                // Overflow (all-0xFF prefix) — unreachable in practice (8-byte long term + 4-byte
379→                // length header = 12 bytes; overflow requires all 12 bytes to be 0xFF).
380→                entries = lsmTree.scan();
381→            }
382→            return new DocIdIterator<>(entries, prefix, docIdSerializer);
383→        }
384→
385→        @Override
386→        public void close() throws IOException {
387→            lsmTree.close();
388→        }
389→
390→        /** Builder for {@link LsmInvertedIndex.LongTermed}. */
391→        public static final class Builder<D> extends AbstractBuilder<D, Builder<D>> {
392→
393→            public InvertedIndex.LongTermed<D> build() {
394→                Objects.requireNonNull(lsmTree, "lsmTree must not be null");
395→                Objects.requireNonNull(docIdSerializer, "docIdSerializer must not be null");
396→                return new LsmInvertedIndex.LongTermed<>(lsmTree, docIdSerializer);
397→            }
398→        }
399→    }
