401→    // -----------------------------------------------------------------------
402→    // SegmentTermed
403→    // -----------------------------------------------------------------------
404→
405→    /**
406→     * An {@link InvertedIndex.SegmentTermed} that delegates to an {@link LsmTree} and uses raw
407→     * {@link MemorySegment} bytes as terms within a composite key.
408→     *
409→     * @param <D> the document ID type
410→     */
411→    public static final class SegmentTermed<D> implements InvertedIndex.SegmentTermed<D> {
412→
413→        private final LsmTree lsmTree;
414→        private final MemorySerializer<D> docIdSerializer;
415→
416→        private SegmentTermed(LsmTree lsmTree, MemorySerializer<D> docIdSerializer) {
417→            assert lsmTree != null : "lsmTree must not be null";
418→            assert docIdSerializer != null : "docIdSerializer must not be null";
