428→            for (MemorySegment term : terms) {
429→                Objects.requireNonNull(term, "term must not be null");
430→                byte[] termBytes = term.toArray(ValueLayout.JAVA_BYTE);
431→                MemorySegment key = compositeKey(termBytes, docIdBytes);
432→                lsmTree.put(key, MemorySegment.NULL);
433→            }
434→        }
435→
436→        @Override
437→        public void remove(D docId, Collection<MemorySegment> terms) throws IOException {
438→            Objects.requireNonNull(docId, "docId must not be null");
439→            Objects.requireNonNull(terms, "terms must not be null");
440→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
441→            for (MemorySegment term : terms) {
442→                Objects.requireNonNull(term, "term must not be null");
443→                byte[] termBytes = term.toArray(ValueLayout.JAVA_BYTE);
444→                MemorySegment key = compositeKey(termBytes, docIdBytes);
445→                lsmTree.delete(key);
446→            }
447→        }
448→
449→        @Override
450→        public Iterator<D> lookup(MemorySegment term) throws IOException {
451→            Objects.requireNonNull(term, "term must not be null");
452→            byte[] termBytes = term.toArray(ValueLayout.JAVA_BYTE);
453→            byte[] prefix = buildPrefix(termBytes);
454→            MemorySegment scanEnd = incrementPrefix(prefix);
455→            Iterator<Entry> entries;
456→            if (scanEnd != null) {
457→                entries = lsmTree.scan(MemorySegment.ofArray(prefix), scanEnd);
458→            } else {
