 78→    static byte[] encodeFloats(float[] floats) {
 79→        assert floats != null : "floats must not be null";
 80→        byte[] bytes = new byte[floats.length * 4];
 81→        for (int i = 0; i < floats.length; i++) {
 82→            int bits = Float.floatToRawIntBits(floats[i]);
 83→            bytes[i * 4] = (byte) (bits >>> 24);
 84→            bytes[i * 4 + 1] = (byte) (bits >>> 16);
 85→            bytes[i * 4 + 2] = (byte) (bits >>> 8);
 86→            bytes[i * 4 + 3] = (byte) bits;
 87→        }
 88→        return bytes;
 89→    }
 90→
 91→    static float[] decodeFloats(byte[] bytes, int dimensions) {
 92→        assert bytes != null : "bytes must not be null";
 93→        assert bytes.length == dimensions * 4 : "byte count mismatch";
 94→        float[] floats = new float[dimensions];
 95→        for (int i = 0; i < dimensions; i++) {
 96→            int bits = ((bytes[i * 4] & 0xFF) << 24) | ((bytes[i * 4 + 1] & 0xFF) << 16)
 97→                    | ((bytes[i * 4 + 2] & 0xFF) << 8) | (bytes[i * 4 + 3] & 0xFF);
 98→            floats[i] = Float.intBitsToFloat(bits);
 99→        }
100→        return floats;
101→    }
