103→    // -----------------------------------------------------------------------
104→    // Float16 encoding helpers
105→    // -----------------------------------------------------------------------
106→
107→    /**
108→     * Encodes a float array to float16 (IEEE 754 binary16) big-endian bytes. Contract: each float
109→     * is converted via {@link Float#floatToFloat16(float)} and stored as 2 bytes big-endian. Output
110→     * length is {@code floats.length * 2}. Side effects: none.
111→     *
112→     * @param floats the float array to encode; must not be null
113→     * @return big-endian float16 byte array of length {@code floats.length * 2}
114→     */
115→    static byte[] encodeFloat16s(float[] floats) {
116→        assert floats != null : "floats must not be null";
117→        byte[] bytes = new byte[floats.length * 2];
118→        for (int i = 0; i < floats.length; i++) {
119→            short bits = Float.floatToFloat16(floats[i]);
120→            bytes[i * 2] = (byte) (bits >>> 8);
121→            bytes[i * 2 + 1] = (byte) bits;
122→        }
123→        return bytes;
124→    }
125→
126→    /**
127→     * Decodes big-endian float16 bytes back to a float array. Contract: each 2-byte pair is read as
128→     * a big-endian short, converted to float via {@link Float#float16ToFloat(short)}. Input length
129→     * must equal {@code dimensions * 2}. Side effects: none.
130→     *
131→     * @param bytes the float16 byte array; must not be null
132→     * @param dimensions the expected number of float components
133→     * @return float array of length {@code dimensions}
134→     */
135→    static float[] decodeFloat16s(byte[] bytes, int dimensions) {
136→        assert bytes != null : "bytes must not be null";
137→        assert bytes.length == dimensions * 2 : "byte count mismatch";
138→        float[] floats = new float[dimensions];
139→        for (int i = 0; i < dimensions; i++) {
140→            short bits = (short) (((bytes[i * 2] & 0xFF) << 8) | (bytes[i * 2 + 1] & 0xFF));
141→            floats[i] = Float.float16ToFloat(bits);
142→        }
143→        return floats;
144→    }
145→
146→    /**
147→     * Encodes a float vector using the specified precision. Contract: dispatches to
148→     * {@link #encodeFloats(float[])} for FLOAT32 or {@link #encodeFloat16s(float[])} for FLOAT16.
149→     * Side effects: none.
150→     *
151→     * @param floats the float array to encode; must not be null
152→     * @param precision the target precision; must not be null
153→     * @return encoded byte array
154→     */
155→    static byte[] encodeVector(float[] floats, VectorPrecision precision) {
156→        assert floats != null : "floats must not be null";
157→        assert precision != null : "precision must not be null";
158→        return switch (precision) {
159→            case FLOAT32 -> encodeFloats(floats);
160→            case FLOAT16 -> encodeFloat16s(floats);
161→        };
162→    }
163→
164→    /**
165→     * Decodes a vector from bytes using the specified precision, returning float[]. Contract:
166→     * dispatches to {@link #decodeFloats(byte[], int)} for FLOAT32 or
167→     * {@link #decodeFloat16s(byte[], int)} for FLOAT16. Side effects: none.
168→     *
169→     * @param bytes the encoded byte array; must not be null
170→     * @param dimensions the expected number of float components
171→     * @param precision the source precision; must not be null
172→     * @return float array of length {@code dimensions}
173→     */
174→    static float[] decodeVector(byte[] bytes, int dimensions, VectorPrecision precision) {
175→        assert bytes != null : "bytes must not be null";
176→        assert precision != null : "precision must not be null";
177→        return switch (precision) {
178→            case FLOAT32 -> decodeFloats(bytes, dimensions);
179→            case FLOAT16 -> decodeFloat16s(bytes, dimensions);
180→        };
181→    }
