327→    /**
328→     * Inverted File Flat (IVF-Flat) vector index.
329→     *
330→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
331→     *
332→     * <pre>
333→     *   [0x00][4-byte BE centroid_id]               → dim×4 bytes (centroid float32 coords)
334→     *   [0x01][4-byte BE centroid_id][doc_id_bytes] → dim×precision bytes (vector coords)
335→     *   [0x02][doc_id_bytes]                        → 4-byte BE centroid_id (reverse lookup)
336→     * </pre>
337→     *
338→     * <h2>Clustering strategy</h2> The first {@code numClusters} indexed vectors become centroids.
339→     * Subsequent vectors are assigned to the nearest centroid (using the configured
340→     * {@link SimilarityFunction}).
341→     */
342→    public static final class IvfFlat<D> implements VectorIndex.IvfFlat<D> {
343→
344→        // Key namespace prefix bytes
345→        private static final byte CENTROID_PREFIX = 0x00;
346→        private static final byte POSTING_PREFIX = 0x01;
347→        private static final byte REVERSE_PREFIX = 0x02;
348→
349→        // Scan bounds: [CENTROID_PREFIX, POSTING_PREFIX) covers all centroid keys
350→        private static final MemorySegment CENTROID_SCAN_START = MemorySegment
351→                .ofArray(new byte[]{ CENTROID_PREFIX });
352→        private static final MemorySegment CENTROID_SCAN_END = MemorySegment
353→                .ofArray(new byte[]{ POSTING_PREFIX });
354→
355→        private final LsmTree lsmTree;
356→        private final MemorySerializer<D> docIdSerializer;
357→        private final int dimensions;
358→        private final SimilarityFunction similarityFunction;
359→        private final int numClusters;
360→        private final int nprobe;
361→        private final VectorPrecision precision;
362→
363→        private IvfFlat(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
364→                SimilarityFunction similarityFunction, int numClusters, int nprobe,
365→                VectorPrecision precision) {
366→            assert lsmTree != null;
367→            assert docIdSerializer != null;
368→            assert dimensions > 0;
369→            assert similarityFunction != null;
370→            assert numClusters > 0;
371→            assert nprobe > 0;
372→            assert precision != null;
373→            this.lsmTree = lsmTree;
374→            this.docIdSerializer = docIdSerializer;
375→            this.dimensions = dimensions;
376→            this.similarityFunction = similarityFunction;
377→            this.numClusters = numClusters;
378→            this.nprobe = nprobe;
379→            this.precision = precision;
380→        }
