387→        @Override
388→        public void index(D docId, float[] vector) throws IOException {
389→            Objects.requireNonNull(docId, "docId must not be null");
390→            Objects.requireNonNull(vector, "vector must not be null");
391→            if (vector.length != dimensions) {
392→                throw new IllegalArgumentException(
393→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
394→            }
395→
396→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
397→            byte[] vectorBytes = encodeVector(vector, precision);
398→
399→            int centroidId = assignCentroid(vector);
400→
401→            // Store posting: [0x01][centroid_id][docId] → vector
402→            lsmTree.put(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)),
403→                    MemorySegment.ofArray(vectorBytes));
404→
405→            // Store reverse lookup: [0x02][docId] → centroid_id (4 bytes BE)
406→            lsmTree.put(MemorySegment.ofArray(reverseKey(docIdBytes)),
407→                    MemorySegment.ofArray(encodeCentroidId(centroidId)));
408→        }
409→
410→        @Override
411→        public void remove(D docId) throws IOException {
412→            Objects.requireNonNull(docId, "docId must not be null");
413→
414→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
415→            byte[] revKey = reverseKey(docIdBytes);
416→
417→            Optional<MemorySegment> revOpt = lsmTree.get(MemorySegment.ofArray(revKey));
418→            if (revOpt.isEmpty())
