 83→                String token = part.replaceAll("[^\\p{L}\\p{N}]", "").toLowerCase(Locale.ROOT);
 84→                if (!token.isEmpty()) {
 85→                    tokens.add(token);
 86→                }
 87→            }
 88→            return tokens;
 89→        }
 90→    }
